{
  "name": "pi-opencodego",
  "version": "0.1.5",
  "description": "Pi extension: OpenCode Go / Zen provider — developer-role compat filter, multi-key rotation + quota awareness + session affinity, and usage/cost tracking",
  "type": "module",
  "main": "./pi/index.ts",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "opencode",
    "opencode-go",
    "zen",
    "deepseek",
    "quota",
    "pi"
  ],
  "files": [
    "pi",
    "src",
    "docs",
    "README.md",
    "README-zh.md"
  ],
  "pi": {
    "extensions": [
      "./pi/index.ts"
    ]
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --experimental-strip-types --test --test-force-exit test/*.test.ts",
    "serve": "node --experimental-strip-types src/serve.ts"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "^0.84.2",
    "@types/node": "^26.2.0",
    "typescript": "^5.6.0"
  }
}
